"""Build the seed-source exclusion list (Phase 0, step 3).

Excluded from being read as a seed source in Phase 2:
  * every absolute path listed in canary_manifest_pass1.csv
  * every file under the ra-ship copy with mtime inside the last 14 days
"""
from __future__ import annotations

import csv
import json
import time
from pathlib import Path

import yaml

HERE = Path(__file__).resolve().parent
CFG = yaml.safe_load((HERE / "config.yaml").read_text(encoding="utf-8"))
ROOT = Path(CFG["output_root"])
RASHIP = Path(CFG["raship_copy"])
MANIFEST = Path("C:/Users/ali/Desktop/canary_manifest_pass1.csv")
FOURTEEN_DAYS = 14 * 86400
SKIP_DIRS = {".git", ".venv", "venv", "node_modules", "__pycache__", "02_tool_runs"}


def norm(p) -> str:
    return str(Path(p)).lower()


def build() -> dict:
    canary_paths, missing = [], []
    if MANIFEST.exists():
        with MANIFEST.open(newline="", encoding="utf-8-sig") as fh:
            for row in csv.DictReader(fh):
                ap = (row.get("absolute_path") or "").strip()
                if ap:
                    canary_paths.append(norm(ap))
    else:
        missing.append(str(MANIFEST))

    now = time.time()
    recent = []
    if RASHIP.exists():
        for p in RASHIP.rglob("*"):
            if any(part in SKIP_DIRS for part in p.parts):
                continue
            if not p.is_file():
                continue
            try:
                if now - p.stat().st_mtime <= FOURTEEN_DAYS:
                    recent.append(norm(p))
            except OSError:
                continue
    else:
        missing.append(str(RASHIP))

    excl = sorted(set(canary_paths) | set(recent))
    out = {
        "built_at": time.strftime("%Y-%m-%dT%H:%M:%S"),
        "manifest": str(MANIFEST),
        "raship_copy": str(RASHIP),
        "cutoff_epoch": now - FOURTEEN_DAYS,
        "cutoff_human": time.strftime("%Y-%m-%d", time.localtime(now - FOURTEEN_DAYS)),
        "n_from_manifest": len(set(canary_paths)),
        "n_recent_mtime": len(set(recent)),
        "missing_inputs": missing,
        "excluded_paths": excl,
    }
    (ROOT / "world").mkdir(parents=True, exist_ok=True)
    (ROOT / "generator" / "exclusion_list.json").write_text(
        json.dumps(out, indent=2), encoding="utf-8"
    )
    return out


def load() -> set:
    f = HERE / "exclusion_list.json"
    if not f.exists():
        return set(build()["excluded_paths"])
    return set(json.loads(f.read_text(encoding="utf-8"))["excluded_paths"])


if __name__ == "__main__":
    o = build()
    print(f"manifest paths : {o['n_from_manifest']}")
    print(f"recent (<=14d) : {o['n_recent_mtime']}")
    print(f"total excluded : {len(o['excluded_paths'])}")
    print(f"cutoff         : {o['cutoff_human']}")
    if o["missing_inputs"]:
        print("MISSING:", o["missing_inputs"])
