"""distractors.py -- Phase 4.

Every distractor is derived mechanically from an answer file, placed in a
*different* branch, and recorded under the question it shadows together with
the reason it is wrong.

Where possible the distractor is a better lexical match for the question than
the answer is: the shadow copy keeps the plain, obvious row label and the
obvious document title, while the correct document uses the drifted label.
"""
from __future__ import annotations

from collections import defaultdict

DISTRACTOR_KINDS = [
    "earlier_vintage", "perturbed_values", "wrong_year_in_header", "preliminary_draft",
    "coauthor_renamed_columns", "other_base_year", "other_unit", "superseded_row_label",
    "scanned_image_only", "inside_archive",
]

# Branches a distractor may be dropped into, by how far they are from a source tree.
FAR_BRANCHES = [
    "Downloads/reports/local think tanks", "Downloads/reports/world bank",
    "Downloads/reports/adb", "Downloads/papers/misc", "Downloads/papers/to read",
    "archive/2024 cleanup/federal", "archive/2024 cleanup/provincial",
    "archive/old drives/thesis backup/Data", ".old_backup/provincial_fiscal_panel/clean",
    "_NEW_STRUCTURE/sources/federal", "_NEW_STRUCTURE/extraction/output",
    "New folder (3)", "Papers/Fiscal decentralisation/replication/data/raw",
    "Papers/Auto sector protection/replication/data/raw",
    "Papers/ADP execution/replication/data/raw", "Papers/Tax effort/replication/data/raw",
    "Conferences/PSDE 2016", "Conferences/NEUDC 2019", "Grants/IGC 2017/submitted",
]


def _coauthor_branches(plan):
    return [d["path"] for d in plan.dirs if d["branch"].startswith("coauthor_")
            and d["depth"] >= 3]


def _why(kind, ctx):
    return {
        "earlier_vintage": (f"Prints the {ctx['old_kind']} vintage published in "
                            f"{ctx['old_year']}; superseded by the {ctx['new_year']} figure."),
        "perturbed_values": (f"Values differ from the published figure by "
                             f"{ctx['pct']:+.1f}% - a working copy that was edited by hand "
                             f"and never reconciled."),
        "wrong_year_in_header": (f"Table header says {ctx['wrong_fy']} but the rows are the "
                                 f"{ctx['right_fy']} observations."),
        "preliminary_draft": "Marked PRELIMINARY - DO NOT CITE on every page; never finalised.",
        "coauthor_renamed_columns": (f"A co-author's copy with columns renamed to the "
                                     f"{ctx['convention']} convention; the values are a stale "
                                     f"extract."),
        "other_base_year": (f"Levels are on base {ctx['other_base']}, not "
                            f"{ctx['right_base']}; not comparable without rescaling."),
        "other_unit": (f"Reported in {ctx['other_unit']} rather than {ctx['right_unit']}; "
                       f"an order-of-magnitude trap."),
        "superseded_row_label": (f"Uses the retired row label '{ctx['old_label']}' for what is "
                                 f"now '{ctx['new_label']}'; the definition changed with it."),
        "scanned_image_only": "A scan with no text layer; the figure cannot be read from it.",
        "inside_archive": ("A copy inside a compressed archive of a folder that also exists "
                           "uncompressed; the uncompressed copy is the one maintained."),
    }[kind]


def derive(plan, world, questions, placed_docs, lo=10, hi=20):
    """Attach distractors to every question that has evidence. Returns a list of
    distractor file records (already placed into the plan)."""
    vmap = {v["vintage_id"]: v for v in world["vintages"]}
    vints = defaultdict(list)
    for v in world["vintages"]:
        vints[v["series_id"]].append(v)
    for k in vints:
        vints[k].sort(key=lambda v: v["published_in"]["year"])
    cat = {d["doc_id"]: d for d in world["catalogue"]}
    series = world["series"]
    coauth = world["entities"]["coauthors"]
    ca_dirs = _coauthor_branches(plan)
    far = [b for b in FAR_BRANCHES if b in plan.by_path]

    out = []
    for q in questions:
        if not q["evidence_addresses"]:
            continue
        g = plan_rng(plan, q["q_id"])
        n = int(g.integers(lo, hi + 1))
        srcs = q["evidence_addresses"]
        for k in range(n):
            ev = srcs[int(g.integers(0, len(srcs)))]
            doc = cat.get(ev["doc_id"])
            kind = DISTRACTOR_KINDS[k % len(DISTRACTOR_KINDS)]
            sid = ev["series_id"]
            v = vmap[ev["vintage_id"]]
            s = series[sid]
            older = [x for x in vints[sid]
                     if x["published_in"]["year"] < v["published_in"]["year"]]
            ctx, spec = {}, {}

            if kind == "earlier_vintage" and older:
                ov = older[-1]
                ctx = {"old_kind": ov["kind"], "old_year": ov["published_in"]["year"],
                       "new_year": v["published_in"]["year"]}
                spec = {"vintage_override": ov["vintage_id"]}
            elif kind == "perturbed_values" or (kind == "earlier_vintage" and not older):
                kind = "perturbed_values"
                pct = float(g.uniform(2.0, 8.0)) * (1 if g.random() < 0.5 else -1)
                ctx = {"pct": pct}
                spec = {"perturb_pct": pct}
            elif kind == "wrong_year_in_header":
                right = ev["fy"]
                yr = int(right.split("-")[0])
                wrong = f"{yr - 1}-{str(yr)[2:]}"
                ctx = {"wrong_fy": wrong, "right_fy": right}
                spec = {"header_fy_override": wrong}
            elif kind == "preliminary_draft":
                spec = {"watermark": "PRELIMINARY - DO NOT CITE"}
            elif kind == "coauthor_renamed_columns":
                ca = coauth[int(g.integers(0, len(coauth)))]
                ctx = {"convention": ca["convention"]}
                spec = {"column_convention": ca["convention"], "coauthor_id": ca["id"]}
                if older:
                    spec["vintage_override"] = older[-1]["vintage_id"]
            elif kind == "other_base_year":
                other = "2015-16" if v["base_year"] == "2005-06" else "2005-06"
                ctx = {"other_base": other, "right_base": v["base_year"]}
                spec = {"base_override": other, "rescale": 0.88 if other == "2015-16" else 1 / 0.88}
            elif kind == "other_unit":
                other = "Rs million" if v["unit"] == "Rs billion" else "Rs billion"
                ctx = {"other_unit": other, "right_unit": v["unit"]}
                spec = {"unit_override": other,
                        "rescale": 1000.0 if other == "Rs million" else 0.001}
            elif kind == "superseded_row_label":
                lv = s["label_variants"]
                old = lv[0] if v["row_label"] != lv[0] else lv[min(1, len(lv) - 1)]
                ctx = {"old_label": old, "new_label": v["row_label"]}
                spec = {"row_label_override": old}
            elif kind == "scanned_image_only":
                spec = {"scanned": True}
            elif kind == "inside_archive":
                spec = {"stage_for_archive": True}

            # --- where it goes -------------------------------------------
            if kind == "coauthor_renamed_columns" and ca_dirs:
                home = ca_dirs[int(g.integers(0, len(ca_dirs)))]
            elif far:
                home = far[int(g.integers(0, len(far)))]
            else:
                home = "Downloads/papers/misc"
            if not plan.room(plan.by_path[home]):
                home = far[int(g.integers(0, len(far)))] if far else home

            # --- what it is called ---------------------------------------
            fmt = "csv" if (kind in ("coauthor_renamed_columns", "other_unit")
                            or g.random() < 0.22) else "pdf"
            base_title = (doc["title"] if doc else s["label"])
            if kind == "scanned_image_only":
                fmt = "pdf"
                fname = f"scan{int(g.integers(10, 99)):04d}.pdf"
            elif fmt == "csv":
                fname = _csv_name(g, s, kind)
            else:
                fname = _pdf_name(g, base_title, kind)

            era = plan.by_path[home]["era"]
            rec = plan.place(
                home, fname, role="distractor", fmt=fmt,
                owner=("pdf" if fmt == "pdf" else "data"), era=era,
                doc_id=f"dx::{q['q_id']}::{k}",
                spec={"kind": "document" if fmt == "pdf" else "series_long",
                      "doc_type": (doc["doc_type"] if doc else "extract"),
                      "title": base_title, "pub_year": (doc["pub_year"] if doc else 2019),
                      "fy": ev["fy"], "target_pages": _pages(g, doc, kind),
                      "fat": False, "era": era, "variant": kind,
                      "series_id": sid, "vintage_id": ev["vintage_id"],
                      "label": s["label"], "unit": v["unit"],
                      "embeds": ([e for e in doc["embeds"]
                                  if e["series_id"] == sid][:3] if doc else []),
                      **spec})
            entry = {"path": rec["path"], "kind": kind, "shadows_q": q["q_id"],
                     "shadows_path": ev["path"], "series_id": sid,
                     "why_wrong": _why(kind, ctx)}
            out.append(entry)
            q["must_not_cite"].append(entry)
    return out


def _pages(g, doc, kind):
    if kind == "scanned_image_only":
        return int(g.integers(5, 16))
    if doc and doc.get("fat"):
        return int(g.integers(20, 60))
    return int(g.integers(4, 30))


def _pdf_name(g, title, kind):
    t = title.replace("/", "-")
    if kind == "preliminary_draft":
        return f"{t} DRAFT.pdf"
    if kind == "wrong_year_in_header":
        return f"{t} (2).pdf"
    if kind == "inside_archive":
        return f"{t} copy.pdf"
    if kind == "other_base_year":
        return f"{t} rebased.pdf"
    if kind == "superseded_row_label":
        return f"{t} old tables.pdf"
    if kind == "earlier_vintage":
        return f"{t}.pdf"
    return f"{t} - {kind.replace('_', ' ')}.pdf"


def _csv_name(g, s, kind):
    stem = s["series_id"]
    if kind == "coauthor_renamed_columns":
        return f"{stem}_shared.csv"
    if kind == "other_unit":
        return f"{stem}_mn.csv"
    if kind == "perturbed_values":
        return f"{stem}_working.csv"
    return f"{stem}_{kind}.csv"


def plan_rng(plan, *key):
    import sys
    from pathlib import Path
    sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "world"))
    import world as W
    return W.rng_for("dx", *key)

