    if kind == "earlier_vintage":
        return f"{t}.pdf"
    return f"{t} - {kind.replace('_', ' ')}.pdf"


def _csv_name(g, s, kind):
    stem = s["series_id"]
    if kind == "coauthor_renamed_columns":
        return f"{stem}_shared.csv"
    if kind == "other_unit":
        return f"{stem}_mn.csv"
    if kind == "perturbed_values":
        return f"{stem}_working.csv"
    return f"{stem}_{kind}.csv"


def plan_rng(plan, *key):
