"""Normalise factory ownership and split the plan into per-factory work lists."""
from __future__ import annotations
import json
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
KEYS = ROOT / "keys"
WORK = KEYS / "work"


def owner_for(f):
    if f["role"] in ("duplicate", "unreadable"):
        return "tail"
    fmt = f["fmt"]
    if fmt == "zip":
        return "tail"
    if fmt in ("docx", "txt"):
        return "tail"
    if fmt == "pdf":
        return "pdf"
    if fmt == "md":
        return "sediment"
    if fmt == "json":
        return "agent"
    return "data"          # csv dta do R xlsx log


def main():
    man = json.loads((KEYS / "skeleton_manifest.json").read_text(encoding="utf-8"))
    files = man["files"]
    for f in files:
        f["owner"] = owner_for(f)
    (KEYS / "skeleton_manifest.json").write_text(json.dumps(man), encoding="utf-8")
    WORK.mkdir(parents=True, exist_ok=True)
    buckets = {}
    for f in files:
        buckets.setdefault(f["owner"], []).append(f)
    for owner, items in buckets.items():
        (WORK / f"{owner}.json").write_text(json.dumps(items), encoding="utf-8")
    (WORK / "dirs.json").write_text(json.dumps(man["dirs"]), encoding="utf-8")
    print("work lists:", {k: len(v) for k, v in sorted(buckets.items())})
    print("by fmt/owner:", dict(Counter((f["owner"], f["fmt"]) for f in files)))


if __name__ == "__main__":
    main()
