"""verify.py -- Phase 9.

Thirteen checks. Every one prints PASS or FAIL with numbers. The build is not
finished until they all pass.

    python verify.py                # everything
    python verify.py 3 4 7          # only those checks
    python verify.py --quick        # skip the slow full-corpus scans
"""
from __future__ import annotations

import hashlib
import json
import os
import re
import sys
import time
import zipfile
from collections import Counter, defaultdict
from concurrent.futures import ProcessPoolExecutor
from datetime import datetime
from pathlib import Path

import yaml

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent
sys.path.insert(0, str(ROOT / "world"))

CFG = yaml.safe_load((HERE / "config.yaml").read_text(encoding="utf-8"))
KEYS = ROOT / "keys"
LADDER = CFG["ladder"]
TOP = LADDER[-1]
MIX = CFG["format_mix"]
ERAS = CFG["eras"]
BUILD_DATE = datetime.now().date()

BANNED = ["canary", "answer", "distractor", "synthetic", "generated", "harness",
          "ground truth", "seed", "test corpus", "filler"]
BANNED_RE = re.compile("|".join(re.escape(b) for b in BANNED), re.IGNORECASE)
TEXT_EXT = {".md", ".txt", ".csv", ".json", ".do", ".r", ".log", ".tex", ".py", ".xml", ".html"}

RESULTS: list[tuple[str, bool, str]] = []


def report(name, ok, detail=""):
    RESULTS.append((name, ok, detail))
    print(f"[{'PASS' if ok else 'FAIL'}] {name}")
    for line in str(detail).splitlines():
        if line.strip():
            print(f"        {line}")
    return ok


def corpus(rung):
    return ROOT / f"corpus_{rung}"


def load_manifest():
    return json.loads((KEYS / "skeleton_manifest.json").read_text(encoding="utf-8"))


def load_key():
    return json.loads((KEYS / "answer_key.json").read_text(encoding="utf-8"))


def load_membership():
    p = KEYS / "rung_membership.json"
    return json.loads(p.read_text(encoding="utf-8")) if p.exists() else {}


def bucket(fmt):
    if fmt in ("pdf", "csv", "md"):
        return fmt
    if fmt == "json":
        return "json_agent"
    return "tail"


def walk_files(root: Path):
    for p in root.rglob("*"):
        if p.is_file():
            yield p


# ==========================================================================
# 1. file counts per rung
# ==========================================================================
def check_1():
    lines, ok = [], True
    for rung in LADDER:
        root = corpus(rung)
        if not root.exists():
            lines.append(f"corpus_{rung}: MISSING")
            ok = False
            continue
        n = sum(1 for _ in walk_files(root))
        dev = (n - rung) / rung
        good = abs(dev) <= 0.03
        ok &= good
        lines.append(f"corpus_{rung}: {n} files, {dev:+.2%} vs target "
                     f"({'within' if good else 'OUTSIDE'} 3%)")
    return report("1. file counts per rung within 3% of ladder", ok, "\n".join(lines))


# ==========================================================================
# 2. format mix per rung
# ==========================================================================
def check_2():
    lines, ok = [], True
    for rung in LADDER:
        root = corpus(rung)
        if not root.exists():
            continue
        c = Counter()
        n = 0
        for p in walk_files(root):
            ext = p.suffix.lower().lstrip(".")
            c[bucket("json" if ext == "json" else ext)] += 1
            n += 1
        for b, want in MIX.items():
            got = c[b] / n if n else 0
            good = abs(got - want) <= 0.03
            ok &= good
            lines.append(f"corpus_{rung} {b:10s} {got:6.2%} vs {want:.2%} "
                         f"({got - want:+.3f}){'' if good else '  OUTSIDE'}")
    return report("2. format mix per rung within 3 points of config", ok, "\n".join(lines))


# ==========================================================================
# 3. fat PDF share and page ranges
# ==========================================================================
def _pagecount(args):
    path, = args
    try:
        from pypdf import PdfReader
        return path, len(PdfReader(path).pages)
    except Exception as exc:
        return path, -1


def check_3(quick=False):
    man = load_manifest()
    files = {f["path"]: f for f in man["files"]}
    root = corpus(TOP)
    lo, hi = CFG["fat_pdf_pages"]
    nlo, nhi = CFG["normal_pdf_pages"]

    fat_expected, normal_expected = [], []
    for rel, f in files.items():
        if f["fmt"] != "pdf":
            continue
        spec = f["spec"]
        src = files.get(spec.get("source_path", "")) if spec.get("kind") == "duplicate" else None
        eff = src["spec"] if src else spec
        (fat_expected if eff.get("fat") else normal_expected).append(rel)

    n_pdf = len(fat_expected) + len(normal_expected)
    share = len(fat_expected) / n_pdf if n_pdf else 0
    want = CFG["fat_pdf_share_of_pdfs"]
    lines = [f"pdfs {n_pdf}, fat {len(fat_expected)} = {share:.2%} (config {want:.2%})"]
    ok = abs(share - want) <= 0.02

    sample = fat_expected if not quick else sorted(fat_expected)[:120]
    paths = [str(root / r) for r in sample if (root / r).exists()]
    bad, unread, counts = [], [], []
    if paths:
        with ProcessPoolExecutor(max_workers=12) as ex:
            for path, n in ex.map(_pagecount, [(p,) for p in paths], chunksize=8):
                if n < 0:
                    unread.append(path)
                else:
                    counts.append(n)
                    if n < 200 or n > hi:
                        bad.append((Path(path).name, n))
    if counts:
        lines.append(f"fat page counts checked with pypdf on {len(counts)} files: "
                     f"min {min(counts)}, max {max(counts)}, mean {sum(counts)/len(counts):.0f}")
    if bad:
        ok = False
        lines.append(f"{len(bad)} fat documents outside 200-{hi} pages, e.g. {bad[:5]}")
    if unread:
        ok = False
        lines.append(f"{len(unread)} fat documents could not be read by pypdf")
    if quick:
        lines.append("(quick mode: page counts sampled, not exhaustive)")
    return report("3. fat-PDF share and page ranges", ok, "\n".join(lines))


# ==========================================================================
# 4. every evidence address resolves
# ==========================================================================
def _page_text(args):
    path, page, title = args
    try:
        from pypdf import PdfReader
        r = PdfReader(path)
        if page is None or page < 0 or page >= len(r.pages):
            return path, page, "RANGE"
        txt = r.pages[page].extract_text() or ""
        norm = " ".join(txt.split())
        return path, page, "OK" if (title and " ".join(title.split()) in norm) else "TITLE"
    except Exception:
        return path, page, "ERROR"


def check_4(quick=False):
    key = load_key()
    root = corpus(TOP)
    addrs = []
    for q in key["questions"]:
        for ev in q["evidence_addresses"]:
            addrs.append((q["q_id"], ev))
    for lk in key.get("relationship_links", []):
        for ev in lk["evidence"]:
            addrs.append(("link", ev))

    missing, badhash, nopage, jobs = [], [], [], []
    for qid, ev in addrs:
        p = root / ev["path"]
        if not p.exists():
            missing.append(ev["path"])
            continue
        if ev.get("content_hash"):
            h = hashlib.sha256()
            with p.open("rb") as fh:
                for chunk in iter(lambda: fh.read(1 << 20), b""):
                    h.update(chunk)
            if h.hexdigest() != ev["content_hash"]:
                badhash.append(ev["path"])
        if ev["path"].lower().endswith(".pdf") and ev.get("page_index") is not None:
            if ev.get("has_text_layer", True) and ev.get("table_title"):
                jobs.append((str(p), ev["page_index"], ev["table_title"]))
        elif ev["path"].lower().endswith(".pdf"):
            nopage.append(ev["path"])

    if quick:
        jobs = jobs[:150]
    range_bad, title_bad, err = [], [], []
    if jobs:
        with ProcessPoolExecutor(max_workers=12) as ex:
            for path, page, status in ex.map(_page_text, jobs, chunksize=4):
                if status == "RANGE":
                    range_bad.append((Path(path).name, page))
                elif status == "TITLE":
                    title_bad.append((Path(path).name, page))
                elif status == "ERROR":
                    err.append(Path(path).name)

    ok = not (missing or badhash or range_bad or title_bad or err)
    lines = [f"{len(addrs)} evidence addresses; {len(jobs)} page-level checks run"]
    for label, lst in [("missing files", missing), ("hash mismatches", badhash),
                       ("page index out of range", range_bad),
                       ("table title not found on that page", title_bad),
                       ("unreadable", err), ("pdf address with no page", nopage)]:
        if lst:
            if label == "pdf address with no page":
                lines.append(f"{label}: {len(lst)} (not fatal; recorded)")
            else:
                lines.append(f"{label}: {len(lst)}  e.g. {lst[:4]}")
    if quick:
        lines.append("(quick mode: page-text checks sampled)")
    return report("4. every evidence address resolves", ok, "\n".join(lines))


# ==========================================================================
# 5. must_not_cite files exist
# ==========================================================================
def check_5():
    key = load_key()
    members = load_membership()
    lines, ok = [], True
    for rung in LADDER:
        root = corpus(rung)
        if not root.exists():
            continue
        member = set(members.get(str(rung), []))
        missing = 0
        total = 0
        for q in key["questions"]:
            for d in q["must_not_cite"]:
                if member and d["path"] not in member:
                    continue           # deliberately not at this rung
                total += 1
                if not (root / d["path"]).exists():
                    missing += 1
        ok &= missing == 0
        lines.append(f"corpus_{rung}: {total} shadow files expected, {missing} missing")
    return report("5. every shadow file named by a question exists", ok, "\n".join(lines))


# ==========================================================================
# 6. absence probes genuinely absent
# ==========================================================================
def _scan_for(args):
    path, needles = args
    try:
        p = Path(path)
        ext = p.suffix.lower()
        if ext == ".zip":
            hits = []
            with zipfile.ZipFile(p) as z:
                for info in z.infolist():
                    if info.file_size > 40 * 1024 * 1024:
                        continue
                    data = z.read(info.filename)
                    txt = data.decode("utf-8", errors="ignore")
                    hits += [n for n in needles if n in txt or n in info.filename]
            return path, sorted(set(hits))
        if ext == ".pdf":
            from pypdf import PdfReader
            r = PdfReader(path)
            txt = "\n".join((pg.extract_text() or "") for pg in r.pages[:40])
        elif ext in TEXT_EXT:
            txt = p.read_text(encoding="utf-8", errors="ignore")
        else:
            txt = ""
        blob = txt + "\n" + p.name
        return path, sorted({n for n in needles if n in blob})
    except Exception:
        return path, []


def check_6(quick=False):
    key = load_key()
    probes = [q["expected_answer"]["absence_probe"] for q in key["questions"]
              if q["type"] == "absence" and q["expected_answer"].get("absence_probe")]
    if not probes:
        return report("6. absence probes genuinely absent", False, "no absence probes in key")
    root = corpus(TOP)
    files = [p for p in walk_files(root)
             if p.suffix.lower() in TEXT_EXT | {".pdf", ".zip"}]
    if quick:
        files = files[::7]
    hits = defaultdict(list)
    with ProcessPoolExecutor(max_workers=12) as ex:
        for path, found in ex.map(_scan_for, [(str(f), probes) for f in files], chunksize=24):
            for n in found:
                hits[n].append(path)
    ok = not hits
    lines = [f"{len(probes)} probes scanned across {len(files)} files (text, pdf and zip members)"]
    for n, where in hits.items():
        lines.append(f"PRESENT: {n!r} in {len(where)} files, e.g. {Path(where[0]).name}")
    if quick:
        lines.append("(quick mode: sampled every 7th file)")
    return report("6. absence probes genuinely absent", ok, "\n".join(lines))


# ==========================================================================
# 7. no experiment vocabulary
# ==========================================================================
def _scan_banned(args):
    path, = args
    p = Path(path)
    out = []
    if BANNED_RE.search(p.name):
        out.append(("name", BANNED_RE.search(p.name).group(0)))
    try:
        ext = p.suffix.lower()
        if ext == ".zip":
            with zipfile.ZipFile(p) as z:
                for info in z.infolist():
                    m = BANNED_RE.search(info.filename)
                    if m:
                        out.append(("zip-name", m.group(0)))
                    if info.file_size > 20 * 1024 * 1024:
                        continue
                    if Path(info.filename).suffix.lower() in TEXT_EXT:
                        m = BANNED_RE.search(z.read(info.filename).decode("utf-8", "ignore"))
                        if m:
                            out.append(("zip-content", m.group(0)))
        elif ext in TEXT_EXT:
            m = BANNED_RE.search(p.read_text(encoding="utf-8", errors="ignore"))
            if m:
                out.append(("content", m.group(0)))
        elif ext == ".pdf":
            from pypdf import PdfReader
            r = PdfReader(path)
            txt = "\n".join((pg.extract_text() or "") for pg in r.pages[:25])
            m = BANNED_RE.search(txt)
            if m:
                out.append(("pdf-text", m.group(0)))
    except Exception:
        pass
    return path, out


def check_7(quick=False):
    root = corpus(TOP)
    bad_dirs = [str(d.relative_to(root)) for d in root.rglob("*")
                if d.is_dir() and BANNED_RE.search(d.name)]
    files = list(walk_files(root))
    if quick:
        files = files[::5]
    hits = []
    with ProcessPoolExecutor(max_workers=12) as ex:
        for path, out in ex.map(_scan_banned, [(str(f),) for f in files], chunksize=24):
            for where, tok in out:
                hits.append((str(Path(path).relative_to(root)), where, tok))
    ok = not hits and not bad_dirs
    lines = [f"scanned {len(files)} files and {sum(1 for _ in root.rglob('*'))} entries"]
    if bad_dirs:
        lines.append(f"{len(bad_dirs)} directory names contain a listed term: {bad_dirs[:5]}")
    if hits:
        c = Counter(t for _, _, t in hits)
        lines.append(f"{len(hits)} content or name hits: {dict(c)}")
        lines.append(f"e.g. {hits[:5]}")
    if quick:
        lines.append("(quick mode: sampled every 5th file)")
    return report("7. no experiment vocabulary in any path or content", ok, "\n".join(lines))


# ==========================================================================
# 8. mtime distribution
# ==========================================================================
def check_8():
    root = corpus(TOP)
    years, today = Counter(), 0
    n = 0
    for p in walk_files(root):
        d = datetime.fromtimestamp(p.stat().st_mtime)
        years[d.year] += 1
        n += 1
        if d.date() == BUILD_DATE:
            today += 1
    era_years = {e: set(range(v["years"][0], v["years"][1] + 1)) for e, v in ERAS.items()}
    got = {e: sum(years[y] for y in ys) / n for e, ys in era_years.items()} if n else {}
    lines = [f"{n} files; year histogram {dict(sorted(years.items()))}",
             f"files carrying the build date ({BUILD_DATE}): {today}"]
    ok = today == 0
    for e, v in ERAS.items():
        want, g = v["weight"], got.get(e, 0)
        good = abs(g - want) <= 0.06
        ok &= good
        lines.append(f"era {e:9s} {g:6.2%} vs weight {want:.0%} "
                     f"({g - want:+.3f}){'' if good else '  OUTSIDE 6 points'}")
    return report("8. mtime distribution plausible, none on the build date", ok, "\n".join(lines))


# ==========================================================================
# 9. determinism
# ==========================================================================
def check_9():
    try:
        import determinism
        ok, detail = determinism.run()
    except Exception as exc:
        ok, detail = False, f"determinism check could not run: {exc}"
    return report("9. determinism: same config reproduces the same bytes", ok, detail)


# ==========================================================================
# 10. exclusion list honoured
# ==========================================================================
def check_10():
    ex = json.loads((HERE / "exclusion_list.json").read_text(encoding="utf-8"))
    excluded = {p.lower() for p in ex["excluded_paths"]}
    logp = ROOT / "logs" / "style_sources_read.log"
    if not logp.exists():
        return report("10. source exclusion list honoured", False,
                      "logs/style_sources_read.log is missing")
    raship = Path(CFG["raship_copy"])
    read_rel = []
    for line in logp.read_text(encoding="utf-8").splitlines():
        m = re.match(r"^\s*\d+\s+(.+?)(?:\s{2,}\(|$)", line)
        if m and ("/" in m.group(1) or m.group(1).endswith(".md")):
            read_rel.append(m.group(1).strip())
    violations, too_new = [], []
    cutoff = ex["cutoff_epoch"]
    for rel in read_rel:
        p = raship / rel
        if str(p).lower() in excluded:
            violations.append(rel)
        if p.exists() and p.stat().st_mtime > cutoff:
            too_new.append(rel)
    ok = not violations and not too_new and len(read_rel) <= 15
    lines = [f"{len(read_rel)} style sources read (cap 15); exclusion list holds "
             f"{len(excluded)} paths, cutoff {ex['cutoff_human']}"]
    if violations:
        lines.append(f"read a path on the exclusion list: {violations}")
    if too_new:
        lines.append(f"read a path modified inside the 14-day window: {too_new}")
    return report("10. source exclusion list honoured", ok, "\n".join(lines))


# ==========================================================================
# 11. unreadable files
# ==========================================================================
def check_11():
    key = load_key()
    root = corpus(TOP)
    want = key.get("unreadable_files", [])
    share = len(want) / TOP if TOP else 0
    lines = [f"{len(want)} intended, {share:.3%} of the tree "
             f"(config {CFG['unreadable_share']:.3%})"]
    ok = abs(share - CFG["unreadable_share"]) <= 0.002
    still_readable = []
    for u in want:
        p = root / u["path"]
        if not p.exists():
            still_readable.append((u["path"], "missing"))
            continue
        kind = u["kind"]
        try:
            if kind in ("truncated_pdf", "encrypted_pdf", "image_only_pdf"):
                from pypdf import PdfReader
                r = PdfReader(str(p))
                if kind == "encrypted_pdf":
                    readable = not r.is_encrypted
                elif kind == "image_only_pdf":
                    readable = bool("".join((pg.extract_text() or "")
                                            for pg in r.pages[:3]).strip())
                else:
                    readable = len(r.pages) > 0
            elif kind == "bad_dta_header":
                import pandas as pd
                pd.read_stata(str(p))
                readable = True
            elif kind == "zero_byte_csv":
                readable = p.stat().st_size > 0
            else:
                readable = True
        except Exception:
            readable = False
        if readable:
            still_readable.append((u["path"], kind))
    ok &= not still_readable
    if still_readable:
        lines.append(f"{len(still_readable)} did not actually fail to parse: "
                     f"{still_readable[:5]}")
    else:
        lines.append("every intended file genuinely fails to parse")
    return report("11. unreadable files present and genuinely unreadable", ok, "\n".join(lines))


# ==========================================================================
# 12. duplicate clusters
# ==========================================================================
def check_12():
    key = load_key()
    root = corpus(TOP)
    clusters = key.get("scattered_duplicate_clusters", []) + [
        {"source_path": c["copies"][0]["path"],
         "copies": [x["path"] for x in c["copies"][1:]]}
        for c in key.get("duplicate_clusters", [])]
    spanning = []
    for c in clusters:
        paths = [c["source_path"]] + c["copies"]
        live = [p for p in paths if (root / p).exists()]
        branches = {p.split("/")[0] for p in live}
        if len(live) >= 2 and len(branches) >= 2:
            spanning.append((c["source_path"], len(live), sorted(branches)[:3]))
    identical = 0
    for c in clusters[:200]:
        src = root / c["source_path"]
        if not src.exists():
            continue
        h = hashlib.sha256(src.read_bytes()).hexdigest() if src.stat().st_size < 5e7 else None
        for cp in c["copies"]:
            p = root / cp
            if p.exists() and h and p.stat().st_size < 5e7:
                if hashlib.sha256(p.read_bytes()).hexdigest() == h:
                    identical += 1
    ok = len(spanning) >= 8
    lines = [f"{len(clusters)} clusters recorded; {len(spanning)} span two or more branches",
             f"byte-identical copies confirmed in the first 200 clusters: {identical}",
             f"examples: {spanning[:3]}"]
    return report("12. at least 8 duplicate clusters spanning 2+ branches", ok, "\n".join(lines))


# ==========================================================================
# 13. script inputs
# ==========================================================================
def check_13():
    man = load_manifest()
    root = corpus(TOP)
    key = load_key()
    intentional = {lk["expected"]["input_path"]
                   for lk in key.get("relationship_links", [])
                   if lk["kind"] == "script_names_input" and not lk["expected"]["input_exists"]}
    scripts = [f for f in man["files"] if f["fmt"] in ("do", "R")]
    missing, checked = [], 0
    pat = re.compile(r"""["']([^"']+\.(?:csv|dta|xlsx|txt|rds|json))["']""", re.IGNORECASE)
    for f in scripts:
        p = root / f["path"]
        if not p.exists():
            continue
        checked += 1
        txt = p.read_text(encoding="utf-8", errors="ignore")
        declared = f["spec"].get("input_path")
        refs = set(pat.findall(txt))
        if declared:
            refs.add(declared)
        for r in refs:
            rr = r.replace("\\", "/").lstrip("./")
            if rr in intentional:
                continue
            if (root / rr).exists():
                continue
            # a bare filename resolved against the script's own folder
            if (p.parent / Path(rr).name).exists():
                continue
            missing.append((f["path"], rr))
    ok = not missing
    lines = [f"{checked} scripts read; {len(intentional)} inputs are intentionally broken",
             f"unaccounted-for references: {len(missing)}"]
    if missing:
        lines.append(f"e.g. {missing[:6]}")
    return report("13. every script input exists or is intentionally broken", ok, "\n".join(lines))


# ==========================================================================
CHECKS = {1: check_1, 2: check_2, 3: check_3, 4: check_4, 5: check_5, 6: check_6,
          7: check_7, 8: check_8, 9: check_9, 10: check_10, 11: check_11,
          12: check_12, 13: check_13}


def main():
    args = [a for a in sys.argv[1:] if not a.startswith("--")]
    quick = "--quick" in sys.argv
    which = [int(a) for a in args] if args else sorted(CHECKS)
    t0 = time.time()
    for i in which:
        fn = CHECKS[i]
        try:
            if fn.__code__.co_argcount == 1:
                fn(quick)
            else:
                fn()
        except Exception as exc:
            import traceback
            report(f"{i}. (crashed)", False, traceback.format_exc()[-1200:])
    n_ok = sum(1 for _, ok, _ in RESULTS if ok)
    print(f"\n{'=' * 66}")
    print(f"{n_ok}/{len(RESULTS)} checks passed in {time.time() - t0:.0f}s")
    for name, ok, _ in RESULTS:
        if not ok:
            print(f"  FAILED: {name}")
    (ROOT / "logs" / "verify_last.json").write_text(
        json.dumps([{"check": n, "pass": o, "detail": d} for n, o, d in RESULTS], indent=1),
        encoding="utf-8")
    sys.exit(0 if n_ok == len(RESULTS) else 1)


if __name__ == "__main__":
    main()

toolUseResult.content:
"""verify.py -- Phase 9.

Thirteen checks. Every one prints PASS or FAIL with numbers. The build is not
finished until they all pass.

    python verify.py                # everything
    python verify.py 3 4 7          # only those checks
    python verify.py --quick        # skip the slow full-corpus scans
"""
from __future__ import annotations

import hashlib
import json
import os
import re
import sys
import time
import zipfile
from collections import Counter, defaultdict
from concurrent.futures import ProcessPoolExecutor
from datetime import datetime
from pathlib import Path

import yaml

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent
sys.path.insert(0, str(ROOT / "world"))

CFG = yaml.safe_load((HERE / "config.yaml").read_text(encoding="utf-8"))
KEYS = ROOT / "keys"
LADDER = CFG["ladder"]
TOP = LADDER[-1]
MIX = CFG["format_mix"]
ERAS = CFG["eras"]
BUILD_DATE = datetime.now().date()

BANNED = ["canary", "answer", "distractor", "synthetic", "generated", "harness",
          "ground truth", "seed", "test corpus", "filler"]
BANNED_RE = re.compile("|".join(re.escape(b) for b in BANNED), re.IGNORECASE)
TEXT_EXT = {".md", ".txt", ".csv", ".json", ".do", ".r", ".log", ".tex", ".py", ".xml", ".html"}

RESULTS: list[tuple[str, bool, str]] = []


def report(name, ok, detail=""):
    RESULTS.append((name, ok, detail))
    print(f"[{'PASS' if ok else 'FAIL'}] {name}")
    for line in str(detail).splitlines():
        if line.strip():
            print(f"        {line}")
    return ok


def corpus(rung):
    return ROOT / f"corpus_{rung}"


def load_manifest():
    return json.loads((KEYS / "skeleton_manifest.json").read_text(encoding="utf-8"))


def load_key():
    return json.loads((KEYS / "answer_key.json").read_text(encoding="utf-8"))


def load_membership():
    p = KEYS / "rung_membership.json"
    return json.loads(p.read_text(encoding="utf-8")) if p.exists() else {}


def bucket(fmt):
    if fmt in ("pdf", "csv", "md"):
        return fmt
    if fmt == "json":
        return "json_agent"
    return "tail"


def walk_files(root: Path):
    for p in root.rglob("*"):
        if p.is_file():
            yield p


# ==========================================================================
# 1. file counts per rung
# ==========================================================================
def check_1():
    lines, ok = [], True
    for rung in LADDER:
        root = corpus(rung)
        if not root.exists():
            lines.append(f"corpus_{rung}: MISSING")
            ok = False
            continue
        n = sum(1 for _ in walk_files(root))
        dev = (n - rung) / rung
        good = abs(dev) <= 0.03
        ok &= good
        lines.append(f"corpus_{rung}: {n} files, {dev:+.2%} vs target "
                     f"({'within' if good else 'OUTSIDE'} 3%)")
    return report("1. file counts per rung within 3% of ladder", ok, "\n".join(lines))


# ==========================================================================
# 2. format mix per rung
# ==========================================================================
def check_2():
    lines, ok = [], True
    for rung in LADDER:
        root = corpus(rung)
        if not root.exists():
            continue
        c = Counter()
        n = 0
        for p in walk_files(root):
            ext = p.suffix.lower().lstrip(".")
            c[bucket("json" if ext == "json" else ext)] += 1
            n += 1
        for b, want in MIX.items():
            got = c[b] / n if n else 0
            good = abs(got - want) <= 0.03
            ok &= good
            lines.append(f"corpus_{rung} {b:10s} {got:6.2%} vs {want:.2%} "
                         f"({got - want:+.3f}){'' if good else '  OUTSIDE'}")
    return report("2. format mix per rung within 3 points of config", ok, "\n".join(lines))


# ==========================================================================
# 3. fat PDF share and page ranges
# ==========================================================================
def _pagecount(args):
    path, = args
    try:
        from pypdf import PdfReader
        return path, len(PdfReader(path).pages)
    except Exception as exc:
        return path, -1


def check_3(quick=False):
    man = load_manifest()
    files = {f["path"]: f for f in man["files"]}
    root = corpus(TOP)
    lo, hi = CFG["fat_pdf_pages"]
    nlo, nhi = CFG["normal_pdf_pages"]

    fat_expected, normal_expected = [], []
    for rel, f in files.items():
        if f["fmt"] != "pdf":
            continue
        spec = f["spec"]
        src = files.get(spec.get("source_path", "")) if spec.get("kind") == "duplicate" else None
        eff = src["spec"] if src else spec
        (fat_expected if eff.get("fat") else normal_expected).append(rel)

    n_pdf = len(fat_expected) + len(normal_expected)
    share = len(fat_expected) / n_pdf if n_pdf else 0
    want = CFG["fat_pdf_share_of_pdfs"]
    lines = [f"pdfs {n_pdf}, fat {len(fat_expected)} = {share:.2%} (config {want:.2%})"]
    ok = abs(share - want) <= 0.02

    sample = fat_expected if not quick else sorted(fat_expected)[:120]
    paths = [str(root / r) for r in sample if (root / r).exists()]
    bad, unread, counts = [], [], []
    if paths:
        with ProcessPoolExecutor(max_workers=12) as ex:
            for path, n in ex.map(_pagecount, [(p,) for p in paths], chunksize=8):
                if n < 0:
                    unread.append(path)
                else:
                    counts.append(n)
                    if n < 200 or n > hi:
                        bad.append((Path(path).name, n))
    if counts:
        lines.append(f"fat page counts checked with pypdf on {len(counts)} files: "
                     f"min {min(counts)}, max {max(counts)}, mean {sum(counts)/len(counts):.0f}")
    if bad:
        ok = False
        lines.append(f"{len(bad)} fat documents outside 200-{hi} pages, e.g. {bad[:5]}")
    if unread:
        ok = False
        lines.append(f"{len(unread)} fat documents could not be read by pypdf")
    if quick:
        lines.append("(quick mode: page counts sampled, not exhaustive)")
    return report("3. fat-PDF share and page ranges", ok, "\n".join(lines))


# ==========================================================================
# 4. every evidence address resolves
# ==========================================================================
def _page_text(args):
    path, page, title = args
    try:
        from pypdf import PdfReader
        r = PdfReader(path)
        if page is None or page < 0 or page >= len(r.pages):
            return path, page, "RANGE"
        txt = r.pages[page].extract_text() or ""
        norm = " ".join(txt.split())
        return path, page, "OK" if (title and " ".join(title.split()) in norm) else "TITLE"
    except Exception:
        return path, page, "ERROR"


def check_4(quick=False):
    key = load_key()
    root = corpus(TOP)
    addrs = []
    for q in key["questions"]:
        for ev in q["evidence_addresses"]:
            addrs.append((q["q_id"], ev))
    for lk in key.get("relationship_links", []):
        for ev in lk["evidence"]:
            addrs.append(("link", ev))

    missing, badhash, nopage, jobs = [], [], [], []
    for qid, ev in addrs:
        p = root / ev["path"]
        if not p.exists():
            missing.append(ev["path"])
            continue
        if ev.get("content_hash"):
            h = hashlib.sha256()
            with p.open("rb") as fh:
                for chunk in iter(lambda: fh.read(1 << 20), b""):
                    h.update(chunk)
            if h.hexdigest() != ev["content_hash"]:
                badhash.append(ev["path"])
        if ev["path"].lower().endswith(".pdf") and ev.get("page_index") is not None:
            if ev.get("has_text_layer", True) and ev.get("table_title"):
                jobs.append((str(p), ev["page_index"], ev["table_title"]))
        elif ev["path"].lower().endswith(".pdf"):
            nopage.append(ev["path"])

    if quick:
        jobs = jobs[:150]
    range_bad, title_bad, err = [], [], []
    if jobs:
        with ProcessPoolExecutor(max_workers=12) as ex:
            for path, page, status in ex.map(_page_text, jobs, chunksize=4):
                if status == "RANGE":
                    range_bad.append((Path(path).name, page))
                elif status == "TITLE":
                    title_bad.append((Path(path).name, page))
                elif status == "ERROR":
                    err.append(Path(path).name)

    ok = not (missing or badhash or range_bad or title_bad or err)
    lines = [f"{len(addrs)} evidence addresses; {len(jobs)} page-level checks run"]
    for label, lst in [("missing files", missing), ("hash mismatches", badhash),
                       ("page index out of range", range_bad),
                       ("table title not found on that page", title_bad),
                       ("unreadable", err), ("pdf address with no page", nopage)]:
        if lst:
            if label == "pdf address with no page":
                lines.append(f"{label}: {len(lst)} (not fatal; recorded)")
            else:
                lines.append(f"{label}: {len(lst)}  e.g. {lst[:4]}")
    if quick:
        lines.append("(quick mode: page-text checks sampled)")
    return report("4. every evidence address resolves", ok, "\n".join(lines))


# ==========================================================================
# 5. must_not_cite files exist
# ==========================================================================
def check_5():
    key = load_key()
    members = load_membership()
    lines, ok = [], True
    for rung in LADDER:
        root = corpus(rung)
        if not root.exists():
            continue
        member = set(members.get(str(rung), []))
        missing = 0
        total = 0
        for q in key["questions"]:
            for d in q["must_not_cite"]:
                if member and d["path"] not in member:
                    continue           # deliberately not at this rung
                total += 1
                if not (root / d["path"]).exists():
                    missing += 1
        ok &= missing == 0
        lines.append(f"corpus_{rung}: {total} shadow files expected, {missing} missing")
    return report("5. every shadow file named by a question exists", ok, "\n".join(lines))


# ==========================================================================
# 6. absence probes genuinely absent
# ==========================================================================
def _scan_for(args):
    path, needles = args
    try:
        p = Path(path)
        ext = p.suffix.lower()
        if ext == ".zip":
            hits = []
            with zipfile.ZipFile(p) as z:
                for info in z.infolist():
                    if info.file_size > 40 * 1024 * 1024:
                        continue
                    data = z.read(info.filename)
                    txt = data.decode("utf-8", errors="ignore")
                    hits += [n for n in needles if n in txt or n in info.filename]
            return path, sorted(set(hits))
        if ext == ".pdf":
            from pypdf import PdfReader
            r = PdfReader(path)
            txt = "\n".join((pg.extract_text() or "") for pg in r.pages[:40])
        elif ext in TEXT_EXT:
            txt = p.read_text(encoding="utf-8", errors="ignore")
        else:
            txt = ""
        blob = txt + "\n" + p.name
        return path, sorted({n for n in needles if n in blob})
    except Exception:
        return path, []


def check_6(quick=False):
    key = load_key()
    probes = [q["expected_answer"]["absence_probe"] for q in key["questions"]
              if q["type"] == "absence" and q["expected_answer"].get("absence_probe")]
    if not probes:
        return report("6. absence probes genuinely absent", False, "no absence probes in key")
    root = corpus(TOP)
    files = [p for p in walk_files(root)
             if p.suffix.lower() in TEXT_EXT | {".pdf", ".zip"}]
    if quick:
        files = files[::7]
    hits = defaultdict(list)
    with ProcessPoolExecutor(max_workers=12) as ex:
        for path, found in ex.map(_scan_for, [(str(f), probes) for f in files], chunksize=24):
            for n in found:
                hits[n].append(path)
    ok = not hits
    lines = [f"{len(probes)} probes scanned across {len(files)} files (text, pdf and zip members)"]
    for n, where in hits.items():
        lines.append(f"PRESENT: {n!r} in {len(where)} files, e.g. {Path(where[0]).name}")
    if quick:
        lines.append("(quick mode: sampled every 7th file)")
    return report("6. absence probes genuinely absent", ok, "\n".join(lines))


# ==========================================================================
# 7. no experiment vocabulary
# ==========================================================================
def _scan_banned(args):
    path, = args
    p = Path(path)
    out = []
    if BANNED_RE.search(p.name):
        out.append(("name", BANNED_RE.search(p.name).group(0)))
    try:
        ext = p.suffix.lower()
        if ext == ".zip":
            with zipfile.ZipFile(p) as z:
                for info in z.infolist():
                    m = BANNED_RE.search(info.filename)
                    if m:
                        out.append(("zip-name", m.group(0)))
                    if info.file_size > 20 * 1024 * 1024:
                        continue
                    if Path(info.filename).suffix.lower() in TEXT_EXT:
                        m = BANNED_RE.search(z.read(info.filename).decode("utf-8", "ignore"))
                        if m:
                            out.append(("zip-content", m.group(0)))
        elif ext in TEXT_EXT:
            m = BANNED_RE.search(p.read_text(encoding="utf-8", errors="ignore"))
            if m:
                out.append(("content", m.group(0)))
        elif ext == ".pdf":
            from pypdf import PdfReader
            r = PdfReader(path)
            txt = "\n".join((pg.extract_text() or "") for pg in r.pages[:25])
            m = BANNED_RE.search(txt)
            if m:
                out.append(("pdf-text", m.group(0)))
    except Exception:
        pass
    return path, out


def check_7(quick=False):
    root = corpus(TOP)
    bad_dirs = [str(d.relative_to(root)) for d in root.rglob("*")
                if d.is_dir() and BANNED_RE.search(d.name)]
    files = list(walk_files(root))
    if quick:
        files = files[::5]
    hits = []
    with ProcessPoolExecutor(max_workers=12) as ex:
        for path, out in ex.map(_scan_banned, [(str(f),) for f in files], chunksize=24):
            for where, tok in out:
                hits.append((str(Path(path).relative_to(root)), where, tok))
    ok = not hits and not bad_dirs
    lines = [f"scanned {len(files)} files and {sum(1 for _ in root.rglob('*'))} entries"]
    if bad_dirs:
        lines.append(f"{len(bad_dirs)} directory names contain a listed term: {bad_dirs[:5]}")
    if hits:
        c = Counter(t for _, _, t in hits)
        lines.append(f"{len(hits)} content or name hits: {dict(c)}")
        lines.append(f"e.g. {hits[:5]}")
    if quick:
        lines.append("(quick mode: sampled every 5th file)")
    return report("7. no experiment vocabulary in any path or content", ok, "\n".join(lines))


# ==========================================================================
# 8. mtime distribution
# ==========================================================================
def check_8():
    root = corpus(TOP)
    years, today = Counter(), 0
    n = 0
    for p in walk_files(root):
        d = datetime.fromtimestamp(p.stat().st_mtime)
        years[d.year] += 1
        n += 1
        if d.date() == BUILD_DATE:
            today += 1
    era_years = {e: set(range(v["years"][0], v["years"][1] + 1)) for e, v in ERAS.items()}
    got = {e: sum(years[y] for y in ys) / n for e, ys in era_years.items()} if n else {}
    lines = [f"{n} files; year histogram {dict(sorted(years.items()))}",
             f"files carrying the build date ({BUILD_DATE}): {today}"]
    ok = today == 0
    for e, v in ERAS.items():
        want, g = v["weight"], got.get(e, 0)
        good = abs(g - want) <= 0.06
        ok &= good
        lines.append(f"era {e:9s} {g:6.2%} vs weight {want:.0%} "
                     f"({g - want:+.3f}){'' if good else '  OUTSIDE 6 points'}")
    return report("8. mtime distribution plausible, none on the build date", ok, "\n".join(lines))


# ==========================================================================
# 9. determinism
# ==========================================================================
def check_9():
    try:
        import determinism
        ok, detail = determinism.run()
    except Exception as exc:
        ok, detail = False, f"determinism check could not run: {exc}"
    return report("9. determinism: same config reproduces the same bytes", ok, detail)


# ==========================================================================
# 10. exclusion list honoured
# ==========================================================================
def check_10():
    ex = json.loads((HERE / "exclusion_list.json").read_text(encoding="utf-8"))
    excluded = {p.lower() for p in ex["excluded_paths"]}
    logp = ROOT / "logs" / "style_sources_read.log"
    if not logp.exists():
        return report("10. source exclusion list honoured", False,
                      "logs/style_sources_read.log is missing")
    raship = Path(CFG["raship_copy"])
    read_rel = []
    for line in logp.read_text(encoding="utf-8").splitlines():
        m = re.match(r"^\s*\d+\s+(.+?)(?:\s{2,}\(|$)", line)
        if m and ("/" in m.group(1) or m.group(1).endswith(".md")):
            read_rel.append(m.group(1).strip())
    violations, too_new = [], []
    cutoff = ex["cutoff_epoch"]
    for rel in read_rel:
        p = raship / rel
        if str(p).lower() in excluded:
            violations.append(rel)
        if p.exists() and p.stat().st_mtime > cutoff:
            too_new.append(rel)
    ok = not violations and not too_new and len(read_rel) <= 15
    lines = [f"{len(read_rel)} style sources read (cap 15); exclusion list holds "
             f"{len(excluded)} paths, cutoff {ex['cutoff_human']}"]
    if violations:
        lines.append(f"read a path on the exclusion list: {violations}")
    if too_new:
        lines.append(f"read a path modified inside the 14-day window: {too_new}")
    return report("10. source exclusion list honoured", ok, "\n".join(lines))


# ==========================================================================
# 11. unreadable files
# ==========================================================================
def check_11():
    key = load_key()
    root = corpus(TOP)
    want = key.get("unreadable_files", [])
    share = len(want) / TOP if TOP else 0
    lines = [f"{len(want)} intended, {share:.3%} of the tree "
             f"(config {CFG['unreadable_share']:.3%})"]
    ok = abs(share - CFG["unreadable_share"]) <= 0.002
    still_readable = []
    for u in want:
        p = root / u["path"]
        if not p.exists():
            still_readable.append((u["path"], "missing"))
            continue
        kind = u["kind"]
        try:
            if kind in ("truncated_pdf", "encrypted_pdf", "image_only_pdf"):
                from pypdf import PdfReader
                r = PdfReader(str(p))
                if kind == "encrypted_pdf":
                    readable = not r.is_encrypted
                elif kind == "image_only_pdf":
                    readable = bool("".join((pg.extract_text() or "")
                                            for pg in r.pages[:3]).strip())
                else:
                    readable = len(r.pages) > 0
            elif kind == "bad_dta_header":
                import pandas as pd
                pd.read_stata(str(p))
                readable = True
            elif kind == "zero_byte_csv":
                readable = p.stat().st_size > 0
            else:
                readable = True
        except Exception:
            readable = False
        if readable:
            still_readable.append((u["path"], kind))
    ok &= not still_readable
    if still_readable:
        lines.append(f"{len(still_readable)} did not actually fail to parse: "
                     f"{still_readable[:5]}")
    else:
        lines.append("every intended file genuinely fails to parse")
    return report("11. unreadable files present and genuinely unreadable", ok, "\n".join(lines))


# ==========================================================================
# 12. duplicate clusters
# ==========================================================================
def check_12():
    key = load_key()
    root = corpus(TOP)
    clusters = key.get("scattered_duplicate_clusters", []) + [
        {"source_path": c["copies"][0]["path"],
         "copies": [x["path"] for x in c["copies"][1:]]}
        for c in key.get("duplicate_clusters", [])]
    spanning = []
    for c in clusters:
        paths = [c["source_path"]] + c["copies"]
        live = [p for p in paths if (root / p).exists()]
        branches = {p.split("/")[0] for p in live}
        if len(live) >= 2 and len(branches) >= 2:
            spanning.append((c["source_path"], len(live), sorted(branches)[:3]))
    identical = 0
    for c in clusters[:200]:
        src = root / c["source_path"]
        if not src.exists():
            continue
        h = hashlib.sha256(src.read_bytes()).hexdigest() if src.stat().st_size < 5e7 else None
        for cp in c["copies"]:
            p = root / cp
            if p.exists() and h and p.stat().st_size < 5e7:
                if hashlib.sha256(p.read_bytes()).hexdigest() == h:
                    identical += 1
    ok = len(spanning) >= 8
    lines = [f"{len(clusters)} clusters recorded; {len(spanning)} span two or more branches",
             f"byte-identical copies confirmed in the first 200 clusters: {identical}",
             f"examples: {spanning[:3]}"]
    return report("12. at least 8 duplicate clusters spanning 2+ branches", ok, "\n".join(lines))


# ==========================================================================
# 13. script inputs
# ==========================================================================
def check_13():
    man = load_manifest()
    root = corpus(TOP)
    key = load_key()
    intentional = {lk["expected"]["input_path"]
                   for lk in key.get("relationship_links", [])
                   if lk["kind"] == "script_names_input" and not lk["expected"]["input_exists"]}
    scripts = [f for f in man["files"] if f["fmt"] in ("do", "R")]
    missing, checked = [], 0
    pat = re.compile(r"""["']([^"']+\.(?:csv|dta|xlsx|txt|rds|json))["']""", re.IGNORECASE)
    for f in scripts:
        p = root / f["path"]
        if not p.exists():
            continue
        checked += 1
        txt = p.read_text(encoding="utf-8", errors="ignore")
        declared = f["spec"].get("input_path")
        refs = set(pat.findall(txt))
        if declared:
            refs.add(declared)
        for r in refs:
            rr = r.replace("\\", "/").lstrip("./")
            if rr in intentional:
                continue
            if (root / rr).exists():
                continue
            # a bare filename resolved against the script's own folder
            if (p.parent / Path(rr).name).exists():
                continue
            missing.append((f["path"], rr))
    ok = not missing
    lines = [f"{checked} scripts read; {len(intentional)} inputs are intentionally broken",
             f"unaccounted-for references: {len(missing)}"]
    if missing:
        lines.append(f"e.g. {missing[:6]}")
    return report("13. every script input exists or is intentionally broken", ok, "\n".join(lines))


# ==========================================================================
CHECKS = {1: check_1, 2: check_2, 3: check_3, 4: check_4, 5: check_5, 6: check_6,
          7: check_7, 8: check_8, 9: check_9, 10: check_10, 11: check_11,
          12: check_12, 13: check_13}


def main():
    args = [a for a in sys.argv[1:] if not a.startswith("--")]
    quick = "--quick" in sys.argv
    which = [int(a) for a in args] if args else sorted(CHECKS)
    t0 = time.time()
    for i in which:
        fn = CHECKS[i]
        try:
            if fn.__code__.co_argcount == 1:
                fn(quick)
            else:
                fn()
        except Exception as exc:
            import traceback
            report(f"{i}. (crashed)", False, traceback.format_exc()[-1200:])
    n_ok = sum(1 for _, ok, _ in RESULTS if ok)
    print(f"\n{'=' * 66}")
    print(f"{n_ok}/{len(RESULTS)} checks passed in {time.time() - t0:.0f}s")
    for name, ok, _ in RESULTS:
        if not ok:
            print(f"  FAILED: {name}")
    (ROOT / "logs" / "verify_last.json").write_text(
        json.dumps([{"check": n, "pass": o, "detail": d} for n, o, d in RESULTS], indent=1),
        encoding="utf-8")
    sys.exit(0 if n_ok == len(RESULTS) else 1)


if __name__ == "__main__":
    main()

